let dependency = {
  name = "late-root-dependency",
  builder = "/bin/sh",
  args = ["-c", "set -eu; /bin/busybox sleep 3; /bin/busybox mkdir -p \"$out\"; /bin/busybox printf 'dependency\\n' > \"$out/value\""],
